fun romanToInt(s: String): Int {
    val v = mapOf('I' to 1, 'V' to 5, 'X' to 10, 'L' to 50, 'C' to 100, 'D' to 500, 'M' to 1000)
    var total = 0
    for (i in s.indices) {
        val cur = v[s[i]]!!
        val next = if (i + 1 < s.length) v[s[i + 1]]!! else 0
        total += if (cur < next) -cur else cur
    }
    return total
}

func run(jobs []Job) []Result {
    in := make(chan Job)
    out := make(chan Result)
    for i := 0; i < 4; i++ {
        go func() {
            for j := range in { out <- process(j) }
            close(out)
        }()
    }
    for _, j := range jobs { in <- j }
    close(in)
    var res []Result
    for r := range out { res = append(res, r) }
    return res
}

