_REGISTRY = {}

def load_plugins(group="acme.plugins"):
    for ep in entry_points(group=group):
        try:
            cls = ep.load()
        except Exception as e:
            log.warning("skip %s: %s", ep.name, e)
            continue
        if getattr(cls, "enabled", True):
