func run(jobs []Job) []Result {
    in := make(chan Job)
    out := make(chan Result)
    var wg sync.WaitGroup
    for w := 0; w < 4; w++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for j := range in {
                r, err := j.Do()
                if err != nil {
                    return
                }
                out <- r
            }
        }()
    }
    go func() {
        for _, j := range jobs { in <- j }
        close(in)
    }()
    wg.Wait()
    close(out)
    var res []Result
    for r := range out { res = append(res, r) }
    return res
}

