int bsearch(int *a, int n, int key) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] < key) lo = mid;
        else hi = mid;
    }
    return (lo < n && a[lo] == key) ? lo : -1;
}

