class Book:
    def __init__(self):
        self.lock = threading.Lock()
        self.sells = {}  # id -> Order
        self.order_locks = defaultdict(threading.Lock)

    def match(self, buy):
        with self.lock:
            candidates = sorted(self.sells.values(), key=lambda o: o.price)
        for s in candidates:
            if s.price > buy.limit:
                break
            with self.order_locks[s.id]:
                if s.filled:
                    continue
                s.filled = True
                with self.lock:
                    del self.sells[s.id]
                return s
        return None

    def cancel(self, order_id):
