typedef struct Block { struct Block *next; } Block;
typedef struct { char *buf; Block *free; size_t sz; } Pool;

void pool_init(Pool *p, size_t obj, size_t n) {
    p->sz = obj < sizeof(Block) ? sizeof(Block) : obj;
    p->buf = malloc(p->sz * n);
    p->free = NULL;
    for (size_t i = 0; i < n; i++) {
        Block *b = (Block *)(p->buf + i * p->sz);
        b->next = p->free;
        p->free = b;
    }
}
void *pool_alloc(Pool *p) {
    Block *b = p->free;
    p->free = b->next;
    return b;
}
void pool_free(Pool *p, void *ptr) {
    Block *b = ptr;
    b->next = p->free;
    p->free = b;
}

func (n *Node) onRequestVote(req VoteReq) VoteResp {
    n.mu.Lock(); defer n.mu.Unlock()
    if req.Term < n.term {
        return VoteResp{Term: n.term, Granted: false}
    }
    if req.Term > n.term {
        n.term = req.Term
        n.state = Follower
    }
    if n.votedFor == "" || n.votedFor == req.Candidate {
        n.votedFor = req.Candidate
        return VoteResp{Term: n.term, Granted: true}
    }
    return VoteResp{Term: n.term, Granted: false}
}

func (n *Node) startElection() {
    n.mu.Lock()
    n.term++
    n.state = Candidate
    n.votedFor = n.id
    term := n.term
    n.mu.Unlock()
    votes := 1
    for _, p := range n.peers {
        go func(p Peer) {
            r := p.RequestVote(VoteReq{Term: term, Candidate: n.id})
            n.mu.Lock(); defer n.mu.Unlock()
            if r.Granted { votes++ }
            if votes > len(n.peers)/2 && n.state == Candidate {
                n.state = Leader
            }
        }(p)
    }
}

