class Emitter {
  private ls: Record<string, Function[]> = {};
  on(e: string, f: Function) { (this.ls[e] ??= []).push(f); }
  off(e: string, f: Function) {
    const arr = this.ls[e]; if (!arr) return;
    arr.splice(arr.indexOf(f), 1);
  }
  once(e: string, f: Function) {
    const w = (...a: any[]) => { this.off(e, w); f(...a); };
