// Invariant: at most one node acts as leader at any wall-clock instant.
// Lease duration L = 5s, max drift D = 50ms.

func (n *Node) loop() {
    for {
        ok, expiry := n.store.TryAcquire(n.id, 5*time.Second) // CAS in etcd, expiry computed by etcd
        if ok {
            n.leaderUntil = time.Now().Add(5 * time.Second)
        }
        time.Sleep(1 * time.Second)
    }
}

func (n *Node) IsLeader() bool {
    return time.Now().Before(n.leaderUntil)
}

func (n *Node) Act() {
    if n.IsLeader() {
        n.doLeaderWork() // may take up to 800ms
    }
}

