struct ring { u32 head, tail; struct entry e[256]; };

/* IRQ context, single producer */
void produce(struct ring *r, struct entry *x) {
    u32 h = r->head;
    if (((h + 1) & 255) == READ_ONCE(r->tail)) return; /* full */
    r->e[h] = *x;
    WRITE_ONCE(r->head, (h + 1) & 255);
}

/* thread context, single consumer */
int consume(struct ring *r, struct entry *out) {
    u32 t = r->tail;
    if (t == READ_ONCE(r->head)) return 0;
    *out = r->e[t];
    smp_mb();
    WRITE_ONCE(r->tail, (t + 1) & 255);
    return 1;
}

