func (f *Follower) AppendEntries(a Args) Reply {
    if a.Term < f.term { return Reply{f.term, false} }
    f.term = a.Term
    if a.PrevIndex > len(f.log)-1 { return Reply{f.term, false} }
    f.log = append(f.log[:a.PrevIndex+1], a.Entries...)
    if a.LeaderCommit > f.commit {
        f.commit = min(a.LeaderCommit, len(f.log)-1)
        f.applyUpTo(f.commit)
    }
    return Reply{f.term, true}
}

